// Notchset reason-popover 2.0.0 · https://notchset.dev/changelog
"use client";
import * as React from "react";
import { Popover } from "@base-ui/react/popover";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/notchset/button";
import { popupPositioner, popupSurface } from "@/lib/notchset/popup";
import { useReturnFocus } from "@/lib/notchset/return-focus";
import { TextField } from "@/components/ui/notchset/text-field";
import { usePortalContainer } from "@/lib/notchset/portal";

/*
 * Reason popover: a step that needs one line of why before it runs (deny a request, decline a quote, pause an
 * account), asked right where it was pressed instead of in a dialog. The question, one field, Cancel and the verb.
 * Enter runs it; an empty reason says what to write and keeps the popover open; a refused save keeps what was
 * typed. On a phone it rises as a sheet. Focus starts in the field and returns to the trigger.
 * A red, irreversible step belongs in a Dialog; this is for steps that Undo can take back.
 */
type ReasonPopoverProps = {
  /** The control that opens it: one element that takes a ref. */
  trigger: React.ReactElement;
  /** The question, as a short heading ("Why deny Q-1047?"). */
  title: React.ReactNode;
  /** The field's label. */
  label: string;
  placeholder?: string | undefined;
  /** The verb that runs it ("Deny"). */
  verb: string;
  /** Said when the field is empty and the verb is pressed. */
  required?: string | undefined;
  /** Runs the step; return an error to show (and stay open), or nothing once it ran. */
  onSubmit: (reason: string) => string | null | undefined | void;
  align?: "start" | "center" | "end" | undefined;
  className?: string | undefined;
};

function ReasonPopover({ trigger, title, label, placeholder, verb, required = "Say why, in a few words", onSubmit, align = "end", className }: ReasonPopoverProps) {
  const portalContainer = usePortalContainer();
  const [open, setOpen] = React.useState(false);
  const returnFocus = useReturnFocus();
  return (
    <Popover.Root open={open} onOpenChange={(o) => setOpen(o)}>
      <Popover.Trigger render={trigger} />
      <Popover.Portal container={portalContainer}>
        <Popover.Positioner side="bottom" align={align} sideOffset={6} collisionPadding={8} className={popupPositioner}>
          <Popover.Popup data-slot="reason-popover" data-ns-layer="" data-ns-moves="" finalFocus={returnFocus} className={cn(popupSurface, "w-[min(320px,calc(100vw-16px))] p-3 max-[600px]:w-auto max-[600px]:px-3 max-[600px]:pt-5 max-[600px]:pb-3", className)}>
            {/* mounted only while open, so each opening starts empty */}
            {open && <ReasonForm title={title} label={label} placeholder={placeholder} verb={verb} required={required} onSubmit={onSubmit} onDone={() => setOpen(false)} />}
          </Popover.Popup>
        </Popover.Positioner>
      </Popover.Portal>
    </Popover.Root>
  );
}

function ReasonForm({ title, label, placeholder, verb, required, onSubmit, onDone }: Omit<ReasonPopoverProps, "trigger" | "align" | "className"> & { onDone: () => void }) {
  const [text, setText] = React.useState("");
  const [err, setErr] = React.useState<string | null>(null);
  const run = () => {
    if (!text.trim()) return setErr(required ?? null);
    const e = onSubmit(text.trim());
    if (e) setErr(e);
    else onDone();
  };
  return (
    <form
      noValidate
      className="flex flex-col gap-3"
      onSubmit={(e) => {
        e.preventDefault();
        run();
      }}
    >
      <Popover.Title className="m-0 text-[length:var(--ns-text-body)] font-[number:var(--ns-weight-medium)] text-[var(--ns-ink)]">{title}</Popover.Title>
      <TextField label={label} placeholder={placeholder} value={text} error={err} autoFocus onChange={(e) => (setText(e.target.value), setErr(null))} />
      <div className="flex justify-end gap-2">
        <Popover.Close render={<Button size="sm">Cancel</Button>} />
        <Button size="sm" type="submit" variant="primary">
          {verb}
        </Button>
      </div>
    </form>
  );
}

export { ReasonPopover, type ReasonPopoverProps };

// Notchset reason-popover 2.0.0 · https://notchset.dev/changelog
/*
 * The one popup surface every list that opens from a control uses (select, combobox, recipient picker, and
 * menus in batch 3): the prototype's .menu. It drops just below its control, and on a phone it becomes a
 * bottom sheet with a grab handle and finger-sized rows. Kept as class strings so each primitive's own parts
 * wear the same look.
 */

/** On the Positioner: above everything but dialogs; on a phone, pinned to the bottom edge as a sheet. */
export const popupPositioner =
  "z-50 outline-hidden max-[600px]:!fixed max-[600px]:!inset-x-2 max-[600px]:!top-auto max-[600px]:!bottom-[calc(8px+env(safe-area-inset-bottom,0px))] max-[600px]:!left-2 max-[600px]:!w-auto max-[600px]:!transform-none";

/** On the Popup. */
export const popupSurface =
  "min-w-[max(var(--anchor-width,0px),180px)] max-h-[min(420px,70vh,var(--available-height,70vh))] overflow-auto overscroll-contain rounded-[var(--ns-radius-lg)] bg-[var(--ns-raised)] p-[5px] text-[length:var(--ns-text-body)] text-[var(--ns-ink)] shadow-[0_0_0_1px_var(--ns-line),var(--ns-shadow-float)] outline-hidden origin-[var(--transform-origin)] " +
  "[animation:ns-menu-in_var(--ns-time-menu)_var(--ns-ease)] data-ending-style:opacity-0 data-ending-style:[transition:opacity_110ms_ease] " +
  "max-[600px]:w-auto max-[600px]:min-w-0 max-[600px]:max-h-[70dvh] max-[600px]:rounded-[var(--ns-radius-xl)] max-[600px]:px-1.5 max-[600px]:pt-3.5 max-[600px]:pb-1.5 max-[600px]:[animation:ns-sheet-up_var(--ns-time-panel)_var(--ns-ease-panel)] " +
  "max-[600px]:before:absolute max-[600px]:before:top-[5px] max-[600px]:before:left-1/2 max-[600px]:before:h-1 max-[600px]:before:w-9 max-[600px]:before:-translate-x-1/2 max-[600px]:before:rounded-full max-[600px]:before:bg-[var(--ns-line)] max-[600px]:before:content-['']";

/** On each item. Highlight (pointer or arrow keys) is the hover wash; the chosen item carries a check. */
export const popupItem =
  "flex w-full min-h-[var(--ns-menu-row)] cursor-default items-center gap-[9px] rounded-[7px] px-[9px] text-left outline-hidden select-none data-highlighted:bg-[var(--ns-hover)] data-disabled:opacity-45 [&_svg:not([data-slot=company-mark])]:size-3.5 [&_svg]:shrink-0";

/** The quiet line a list shows when nothing matches. */
export const popupEmpty = "px-[9px] py-2 text-[length:var(--ns-text-small)] text-[var(--ns-ink-3)] empty:hidden";

// Notchset reason-popover 2.0.0 · https://notchset.dev/changelog
import * as React from "react";

/*
 * Where overlays (dialogs, menus, popovers, tooltips, toasts, sheets) portal to. By default the document body; a
 * host that themes or scopes a region (a preview stage, a shadow root, a tile in another theme) wraps it in
 * PortalContainer with an element inside that scope, so its overlays keep the region's roles and light or dark.
 */
const PortalContainerContext = React.createContext<HTMLElement | null>(null);

const PortalContainer = PortalContainerContext.Provider;

/** The element overlays portal into here, or undefined for the document body. */
function usePortalContainer(): HTMLElement | undefined {
  return React.useContext(PortalContainerContext) ?? undefined;
}

export { PortalContainer, PortalContainerContext, usePortalContainer };

// Notchset reason-popover 2.0.0 · https://notchset.dev/changelog
"use client";
import * as React from "react";

/*
 * Focus goes back to whatever opened a layer when it closes, even when the layer is opened from state (a menu
 * item, a shortcut, a row) rather than its own trigger. One document listener remembers the last control
 * focused or pressed outside any layer (marked data-ns-layer); pressing counts too because Safari does not focus
 * a clicked button. Pass the result to a Base UI Popup's finalFocus.
 */
let last: HTMLElement | null = null;
let watching = false;

function watch() {
  if (watching || typeof document === "undefined") return;
  watching = true;
  const note = (e: Event) => {
    const t = e.target as HTMLElement | null;
    if (!t?.closest || t.closest("[data-ns-layer]")) return;
    /* a table row that opens on press is its own opener: it takes focus back (as a J/K row does), so closing
       what it opened never leaves focus on the page's body, where the next Tab can leave the app */
    const row = t.closest<HTMLElement>("tr[data-row]");
    const ctl = t.closest<HTMLElement>("button,a[href],input,select,textarea,[tabindex]");
    if (row && (!ctl || !row.contains(ctl)) && !row.hasAttribute("tabindex")) row.tabIndex = -1;
    last = (row && (!ctl || !row.contains(ctl)) ? row : ctl) ?? last;
  };
  document.addEventListener("focusin", note, true);
  document.addEventListener("pointerdown", note, true);
}

export function useReturnFocus() {
  React.useEffect(watch, []);
  return React.useCallback(() => (last && last.isConnected ? last : true), []);
}
